O2=[[5,5,5],[5,5,5],[5,1,1]]
def blocks(G,sep):
    h=len(G);w=len(G[0])
    rsep=[r for r in range(h) if all(G[r][c]==sep for c in range(w))]
    csep=[c for c in range(w) if all(G[r][c]==sep for r in range(h))]
    def groups(n,seps):
        gs=[];s=0
        for x in seps+ [n]:
            if x>s: gs.append(list(range(s,x)))
            s=x+1
        return gs
    return groups(h,rsep),groups(w,csep)
